function serializeQuery(pairs) {
  if (!Array.isArray(pairs)) {
    throw new TypeError("Expected an array");
  }

  const hasOwn = Object.prototype.hasOwnProperty;
  const encoded = new Array(pairs.length);

  for (let i = 0; i < pairs.length; i++) {
    if (!hasOwn.call(pairs, i)) {
      throw new TypeError("Sparse arrays are not supported");
    }

    const pair = pairs[i];

    if (
      !Array.isArray(pair) ||
      pair.length !== 2 ||
      !hasOwn.call(pair, 0) ||
      !hasOwn.call(pair, 1) ||
      typeof pair[0] !== "string" ||
      typeof pair[1] !== "string"
    ) {
      throw new TypeError("Each item must be a dense two-element string array");
    }

    encoded[i] = [encodeRFC3986(pair[0]), encodeRFC3986(pair[1])];
  }

  encoded.sort((a, b) => {
    const nameOrder = compareASCII(a[0], b[0]);
    return nameOrder !== 0 ? nameOrder : compareASCII(a[1], b[1]);
  });

  return encoded.map(pair => pair[0] + "=" + pair[1]).join("&");
}

function compareASCII(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function encodeRFC3986(value) {
  let result = "";

  for (let i = 0; i < value.length; i++) {
    let codePoint = value.charCodeAt(i);

    if (codePoint >= 0xd800 && codePoint <= 0xdbff) {
      if (i + 1 >= value.length) {
        throw new URIError("Unpaired UTF-16 surrogate");
      }

      const low = value.charCodeAt(++i);

      if (low < 0xdc00 || low > 0xdfff) {
        throw new URIError("Unpaired UTF-16 surrogate");
      }

      codePoint =
        0x10000 + ((codePoint - 0xd800) << 10) + (low - 0xdc00);
    } else if (codePoint >= 0xdc00 && codePoint <= 0xdfff) {
      throw new URIError("Unpaired UTF-16 surrogate");
    }

    if (
      codePoint >= 0x41 && codePoint <= 0x5a ||
      codePoint >= 0x61 && codePoint <= 0x7a ||
      codePoint >= 0x30 && codePoint <= 0x39 ||
      codePoint === 0x2d ||
      codePoint === 0x2e ||
      codePoint === 0x5f ||
      codePoint === 0x7e
    ) {
      result += String.fromCodePoint(codePoint);
      continue;
    }

    if (codePoint <= 0x7f) {
      result += percentByte(codePoint);
    } else if (codePoint <= 0x7ff) {
      result += percentByte(0xc0 | (codePoint >> 6));
      result += percentByte(0x80 | (codePoint & 0x3f));
    } else if (codePoint <= 0xffff) {
      result += percentByte(0xe0 | (codePoint >> 12));
      result += percentByte(0x80 | ((codePoint >> 6) & 0x3f));
      result += percentByte(0x80 | (codePoint & 0x3f));
    } else {
      result += percentByte(0xf0 | (codePoint >> 18));
      result += percentByte(0x80 | ((codePoint >> 12) & 0x3f));
      result += percentByte(0x80 | ((codePoint >> 6) & 0x3f));
      result += percentByte(0x80 | (codePoint & 0x3f));
    }
  }

  return result;
}

function percentByte(byte) {
  return "%" + byte.toString(16).toUpperCase().padStart(2, "0");
}
